import{_ as e,o as i,c as s,ai as a}from"./chunks/framework.Ba-VnP44.js";const m=JSON.parse('{"title":"AI 辅助软件开发规范","description":"","frontmatter":{},"headers":[],"relativePath":"ai/productivity/dev-spec/index.md","filePath":"ai/productivity/dev-spec/index.md"}'),l={name:"ai/productivity/dev-spec/index.md"};function r(n,t,p,d,c,o){return i(),s("div",null,[...t[0]||(t[0]=[a(`<h1 id="ai-辅助软件开发规范" tabindex="-1">AI 辅助软件开发规范 <a class="header-anchor" href="#ai-辅助软件开发规范" aria-label="Permalink to “AI 辅助软件开发规范”">​</a></h1><blockquote><p>V1.0 · 一套完整的工程规范，而不只是提示词集合。它把「AI 如何理解项目、如何规范完成一项开发任务、如何证明结果可靠」组织成三个互相支撑的层次。</p></blockquote><h2 id="为什么需要一套规范" tabindex="-1">为什么需要一套规范 <a class="header-anchor" href="#为什么需要一套规范" aria-label="Permalink to “为什么需要一套规范”">​</a></h2><p>零散的提示词能解决单点问题，但解决不了三件事：AI 每次都要重新理解项目、同类任务每次做法不一样、做完之后说不清「改了什么、验证过没有、能不能回滚」。</p><p>这套规范把这三件事固定下来：</p><ul><li><strong>能力可复用</strong>：项目背景、规则、技能、分工方式沉淀在仓库里，不用每次对话重新交代。</li><li><strong>过程可预期</strong>：任何一项开发任务，从准备到交付都有明确的阶段和判断标准。</li><li><strong>结果可验证</strong>：质量、安全、变更、回滚贯穿全程，而不是收工时补一串检查。</li></ul><h2 id="三个层次" tabindex="-1">三个层次 <a class="header-anchor" href="#三个层次" aria-label="Permalink to “三个层次”">​</a></h2><table tabindex="0"><thead><tr><th>层次</th><th>目标</th><th>包含什么</th></tr></thead><tbody><tr><td><a href="/my-vitepress-site/ai/productivity/dev-spec/01-foundation/project-context.html">第一层 · AI 工程基础</a></td><td>让 AI 正确工作</td><td>Project Context · Rules · Skills · Agents · MCP / Tools · Hooks / Scripts</td></tr><tr><td><a href="/my-vitepress-site/ai/productivity/dev-spec/02-lifecycle/project-prep.html">第二层 · 软件开发生命周期</a></td><td>让开发过程规范</td><td>项目准备 → 需求分析 → 架构设计 → 功能开发 → 审查 → 修复 → 优化 → 测试 → 交付</td></tr><tr><td><a href="/my-vitepress-site/ai/productivity/dev-spec/03-quality/code-quality.html">第三层 · 质量与安全保障</a></td><td>确保结果可靠</td><td>代码质量 · 测试验证 · 数据安全 · Git 管理 · 变更控制 · 交付追踪</td></tr></tbody></table><p>三者是支撑关系，不是并列关系：</p><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>┌─────────────────────────────────────────────┐</span></span>
<span class="line"><span>│  第三层 · 质量与安全保障（全程贯穿）            │</span></span>
<span class="line"><span>│  代码质量 · 测试验证 · 数据安全 · Git · 变更 · 追踪 │</span></span>
<span class="line"><span>├─────────────────────────────────────────────┤</span></span>
<span class="line"><span>│  第二层 · 软件开发生命周期（执行流程）           │</span></span>
<span class="line"><span>│  准备 → 需求 → 架构 → 开发 → 审查 → 修复 → 优化 → 测试 → 交付 │</span></span>
<span class="line"><span>├─────────────────────────────────────────────┤</span></span>
<span class="line"><span>│  第一层 · AI 工程基础（能力底座）               │</span></span>
<span class="line"><span>│  Context · Rules · Skills · Agents · MCP · Hooks │</span></span>
<span class="line"><span>└─────────────────────────────────────────────┘</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div><p>关键关系：</p><ul><li>第一层是整个体系的<strong>能力基础</strong>，决定 AI 能不能正确理解项目和调用能力。</li><li>第二层是实际工作的<strong>执行流程</strong>，决定一项任务怎么从开始走到结束。</li><li>第三层是贯穿前两层的<strong>保障机制</strong>——它从项目准备就生效，不是等开发结束才执行。</li></ul><h2 id="两层协同示例" tabindex="-1">两层协同示例 <a class="header-anchor" href="#两层协同示例" aria-label="Permalink to “两层协同示例”">​</a></h2><p>开发生产报工功能：</p><table tabindex="0"><thead><tr><th>层次</th><th>AI 在做什么</th></tr></thead><tbody><tr><td>AI 工程基础</td><td>读取项目 Rules、MES 业务文档，按需调用数据库设计 Skill</td></tr><tr><td>软件开发生命周期</td><td>分析需求、设计架构、开发报工功能、审查、测试、交付</td></tr><tr><td>质量与安全保障</td><td>检查事务、权限、数据一致性、Git Diff、测试结果和回滚方案</td></tr></tbody></table><p>后续出现库存数量错误：</p><table tabindex="0"><thead><tr><th>层次</th><th>AI 在做什么</th></tr></thead><tbody><tr><td>AI 工程基础</td><td>读取业务规则，调用问题诊断 Skill</td></tr><tr><td>软件开发生命周期</td><td>定位库存逻辑问题、修复、回归测试</td></tr><tr><td>质量与安全保障</td><td>验证库存一致性、检查数据库变更、保护已有代码</td></tr></tbody></table><h2 id="完整目录" tabindex="-1">完整目录 <a class="header-anchor" href="#完整目录" aria-label="Permalink to “完整目录”">​</a></h2><details><summary><strong>第一层 · AI 工程基础（6 页）</strong></summary><ul><li><a href="/my-vitepress-site/ai/productivity/dev-spec/01-foundation/project-context.html">Project Context · 项目上下文</a> — 让 AI 按需拿到准确的项目信息</li><li><a href="/my-vitepress-site/ai/productivity/dev-spec/01-foundation/rules.html">Rules · 项目规则</a> — 把长期约束写成 AI 必须遵守的规则</li><li><a href="/my-vitepress-site/ai/productivity/dev-spec/01-foundation/skills.html">Skills · 专业技能</a> — 把重复做法固化为可调用的技能</li><li><a href="/my-vitepress-site/ai/productivity/dev-spec/01-foundation/agents.html">Agents · 智能体协作</a> — 明确谁来做什么、权限到哪</li><li><a href="/my-vitepress-site/ai/productivity/dev-spec/01-foundation/mcp-tools.html">MCP / Tools · 工具与外部能力</a> — 让 AI 安全地连接仓库外的能力</li><li><a href="/my-vitepress-site/ai/productivity/dev-spec/01-foundation/hooks-scripts.html">Hooks / Scripts · 自动化执行</a> — 把确定性检查交给脚本</li></ul></details><details><summary><strong>第二层 · 软件开发生命周期（9 页）</strong></summary><ul><li><a href="/my-vitepress-site/ai/productivity/dev-spec/02-lifecycle/project-prep.html">01 项目准备</a></li><li><a href="/my-vitepress-site/ai/productivity/dev-spec/02-lifecycle/requirement-analysis.html">02 需求分析</a></li><li><a href="/my-vitepress-site/ai/productivity/dev-spec/02-lifecycle/architecture-design.html">03 技术架构设计</a></li><li><a href="/my-vitepress-site/ai/productivity/dev-spec/02-lifecycle/development.html">04 功能开发</a></li><li><a href="/my-vitepress-site/ai/productivity/dev-spec/02-lifecycle/review.html">05 功能审查与完善</a></li><li><a href="/my-vitepress-site/ai/productivity/dev-spec/02-lifecycle/bugfix.html">06 逻辑与 BUG 修复</a></li><li><a href="/my-vitepress-site/ai/productivity/dev-spec/02-lifecycle/refactor.html">07 代码优化与重构</a></li><li><a href="/my-vitepress-site/ai/productivity/dev-spec/02-lifecycle/testing.html">08 代码测试</a></li><li><a href="/my-vitepress-site/ai/productivity/dev-spec/02-lifecycle/delivery.html">09 交付与复用</a></li></ul></details><details><summary><strong>第三层 · 质量与安全保障（6 页）</strong></summary><ul><li><a href="/my-vitepress-site/ai/productivity/dev-spec/03-quality/code-quality.html">代码质量规范</a></li><li><a href="/my-vitepress-site/ai/productivity/dev-spec/03-quality/test-verification.html">测试与验证规范</a></li><li><a href="/my-vitepress-site/ai/productivity/dev-spec/03-quality/data-security.html">数据与安全规范</a></li><li><a href="/my-vitepress-site/ai/productivity/dev-spec/03-quality/git-version.html">Git 与版本管理</a></li><li><a href="/my-vitepress-site/ai/productivity/dev-spec/03-quality/change-control.html">变更控制</a></li><li><a href="/my-vitepress-site/ai/productivity/dev-spec/03-quality/delivery-rollback.html">交付追踪与回滚</a></li></ul></details><h2 id="怎么使用这套规范" tabindex="-1">怎么使用这套规范 <a class="header-anchor" href="#怎么使用这套规范" aria-label="Permalink to “怎么使用这套规范”">​</a></h2><details><summary><strong>按任务轻重裁剪，不要每次都走完整流程</strong></summary><table tabindex="0"><thead><tr><th>任务类型</th><th>建议做法</th></tr></thead><tbody><tr><td>改文案、明确的小修</td><td>直接执行 + 局部检查，跳过大部分阶段</td></tr><tr><td>小 Bug</td><td>准备 → 修复 → 验证，重点用第三层排查闭环</td></tr><tr><td>普通功能</td><td>需求 → 方案 → 开发 → 审查 → 测试 → 交付</td></tr><tr><td>复杂功能 / 老项目改造</td><td>完整走九阶段 + 三层保障全程生效</td></tr></tbody></table><p>判断标准：<strong>改错了需要回滚多个文件，就按完整流程走</strong>。</p></details><details><summary><strong>日常最短路径</strong></summary><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>① 准备    AI 读项目上下文和规则（第一层 + 项目准备）</span></span>
<span class="line"><span>② 说清    目标 + 约束 + 验收讲明白（需求分析）</span></span>
<span class="line"><span>③ 执行    简单任务直接做；复杂任务先方案后拆解（架构→开发）</span></span>
<span class="line"><span>④ 收尾    审查 + 测试 + 安全检查 + 交付报告（审查→测试→交付 + 第三层）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div></details><h2 id="与其他栏目的边界" tabindex="-1">与其他栏目的边界 <a class="header-anchor" href="#与其他栏目的边界" aria-label="Permalink to “与其他栏目的边界”">​</a></h2><ul><li>本规范讲<strong>流程、判断标准和验收要求</strong>，是可执行的工程规范。</li><li>可直接复制的零散提示词，仍见 <a href="/my-vitepress-site/ai/prompts/coding.html">提示词库 · 编程开发</a>；本规范各阶段只放与该阶段强相关的提示词，不重复维护大段模板。</li><li>术语衔接见 <a href="/my-vitepress-site/ai/productivity/ai-coding-workflow.html">AI 辅助编程工作流</a>。</li><li>工具选型见 <a href="/my-vitepress-site/ai/productivity/tool-selection.html">AI 工具与选型</a>。</li></ul><blockquote><p>具体工具的目录名、配置语法、加载方式以各工具当前版本官方文档为准。本规范里的文件名和目录都是通用示意，不把某个工具的约定当成行业标准。</p></blockquote>`,27)])])}const u=e(l,[["render",r]]);export{m as __pageData,u as default};
